#!/usr/bin/env node
'use strict';

/**
 * Runs an ECC hook under the Continue CLI (`cn`).
 *
 * cn implements Claude Code's hook protocol (same events, stdin JSON, exit
 * code 2 = block) but its tool names and inputs differ slightly. This adapter
 * rewrites the payload into the Claude Code shape ECC hooks expect, then runs
 * the hook and passes stdout, stderr and the exit code straight back.
 *
 * Usage (generated by scripts/install-continue.js):
 *   node continue-hook-adapter.js run <hookId> <script> <profilesCsv>
 *   node continue-hook-adapter.js direct <script>
 * Either form may be prefixed with `--profile <minimal|standard|strict>`, used
 * as ECC_HOOK_PROFILE unless that variable is already set.
 */

const path = require('path');
const { spawnSync } = require('child_process');
const { CONTINUE_TO_CLAUDE_TOOLS } = require('../lib/continue-cli');

const ECC_ROOT = path.resolve(__dirname, '..', '..');
const MAX_STDIN = 4 * 1024 * 1024;

/**
 * Hooks that assume Claude Code internals. Disabled unless the user sets
 * ECC_DISABLED_HOOKS themselves (set it to "" to re-enable everything).
 */
const DEFAULT_DISABLED = [
  'pre:bash:gateguard-fact-force',
  'pre:edit-write:gateguard-fact-force',
  'pre:bash:auto-tmux-dev',
].join(',');

/**
 * Convert a cn hook payload into the Claude Code shape.
 * @param {object} input parsed stdin JSON
 * @returns {object}
 */
function normalizePayload(input) {
  if (!input || typeof input !== 'object') return input;
  const out = { ...input };
  if (typeof out.tool_name === 'string' && CONTINUE_TO_CLAUDE_TOOLS[out.tool_name]) {
    out.continue_tool_name = out.tool_name;
    out.tool_name = CONTINUE_TO_CLAUDE_TOOLS[out.tool_name];
  }
  if (out.tool_input && typeof out.tool_input === 'object' && !Array.isArray(out.tool_input)) {
    const ti = { ...out.tool_input };
    // cn Read/Write use `filepath`; Claude Code (and ECC hooks) use `file_path`.
    if (ti.filepath && !ti.file_path) ti.file_path = ti.filepath;
    if (Array.isArray(ti.edits) && ti.file_path) {
      ti.edits = ti.edits.map(e => (e && typeof e === 'object' && !e.file_path ? { ...e, file_path: ti.file_path } : e));
    }
    out.tool_input = ti;
  }
  return out;
}

function buildEnv(base, profile) {
  const env = { ...base, CLAUDE_PLUGIN_ROOT: ECC_ROOT, ECC_PLUGIN_ROOT: ECC_ROOT, ECC_HARNESS: 'continue' };
  if (env.ECC_DISABLED_HOOKS === undefined) env.ECC_DISABLED_HOOKS = DEFAULT_DISABLED;
  if (profile && !env.ECC_HOOK_PROFILE) env.ECC_HOOK_PROFILE = profile;
  if (!env.CLAUDE_PROJECT_DIR && env.CONTINUE_PROJECT_DIR) env.CLAUDE_PROJECT_DIR = env.CONTINUE_PROJECT_DIR;
  return env;
}

/** Resolve the node argv for a hook invocation, refusing paths outside ECC. */
function resolveCommand(argv) {
  const [mode, ...rest] = argv;
  const inside = rel => {
    const abs = path.resolve(ECC_ROOT, rel || '');
    if (!rel || !abs.startsWith(path.join(ECC_ROOT, 'scripts', 'hooks') + path.sep)) {
      throw new Error(`hook script must live in scripts/hooks: ${rel}`);
    }
    return abs;
  };
  if (mode === 'direct') return [inside(rest[0])];
  if (mode === 'run') {
    const [id, script, profiles] = rest;
    if (!id) throw new Error('missing hook id');
    inside(script);
    return [path.join(ECC_ROOT, 'scripts', 'hooks', 'run-with-flags.js'), id, script, profiles || 'standard,strict'];
  }
  throw new Error(`unknown mode "${mode}" (expected run|direct)`);
}

function readStdin() {
  return new Promise(resolve => {
    const chunks = [];
    let size = 0;
    process.stdin.on('data', c => {
      size += c.length;
      if (size <= MAX_STDIN) chunks.push(c);
    });
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    process.stdin.on('error', () => resolve(''));
  });
}

/** Split an optional leading `--profile <p>` off the argv. */
function splitProfile(argv) {
  if (argv[0] === '--profile') return { profile: argv[1], rest: argv.slice(2) };
  return { profile: undefined, rest: argv };
}

async function main() {
  const { profile, rest } = splitProfile(process.argv.slice(2));
  let args;
  try {
    args = resolveCommand(rest);
  } catch (err) {
    process.stderr.write(`[ContinueHookAdapter] ${err.message}\n`);
    return 0; // misconfiguration must never block the user's tool call
  }
  const raw = await readStdin();
  let payload = raw;
  try {
    payload = JSON.stringify(normalizePayload(JSON.parse(raw)));
  } catch {
    // Pass non-JSON input through untouched; ECC hooks handle it themselves.
  }
  const result = spawnSync(process.execPath, args, {
    input: payload,
    cwd: process.cwd(),
    env: buildEnv(process.env, profile),
    encoding: 'utf8',
    maxBuffer: 16 * 1024 * 1024,
  });
  if (result.error) {
    process.stderr.write(`[ContinueHookAdapter] ${result.error.message}\n`);
    return 0;
  }
  if (result.stdout) process.stdout.write(result.stdout);
  if (result.stderr) process.stderr.write(result.stderr);
  return typeof result.status === 'number' ? result.status : 0;
}

if (require.main === module) {
  main().then(code => { process.exitCode = code; });
}

module.exports = { normalizePayload, buildEnv, resolveCommand, splitProfile, DEFAULT_DISABLED, ECC_ROOT };
